import React, { useState, useEffect, useRef } from "react";
import "./App.css";

function TypingIndicator() {
  return (
    <div className="typing-indicator">
      <span></span><span></span><span></span>
    </div>
  );
}

function App() {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([]);
  const [typing, setTyping] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, typing]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMessage = {
      id: Date.now(),
      text: input,
      sender: "user",
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setTyping(true);

    try {
      const response = await fetch("http://localhost:8000/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: input }),
      });
      const data = await response.json();

      const botMessage = {
        id: Date.now() + 1,
        text: data.response || "Sorry, no response.",
        sender: "bot",
        time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      };

      // Simulate typing delay for realism
      setTimeout(() => {
        setMessages((prev) => [...prev, botMessage]);
        setTyping(false);
      }, 800);
    } catch (error) {
      console.error("Error:", error);
      setTyping(false);
    }
  };

  return (
    <div className={`app ${darkMode ? "dark" : "light"}`}>
      <header className="app-header">
        <h1>ABC College Chatbot</h1>
        <button
          className="theme-toggle"
          aria-label="Toggle Dark Mode"
          onClick={() => setDarkMode(!darkMode)}
        >
          {darkMode ? "☀️ Light" : "🌙 Dark"}
        </button>
      </header>

      <main className="chat-container" role="main" aria-live="polite">
        <div className="messages">
          {messages.map(({ id, text, sender, time }) => (
            <div key={id} className={`message ${sender}`} tabIndex={0}>
              <p className="message-text">{text}</p>
              <span className="timestamp" aria-label={`Sent at ${time}`}>{time}</span>
            </div>
          ))}
          {typing && (
            <div className="message bot typing" aria-live="assertive" aria-atomic="true">
              <p className="message-text">Bot is typing <TypingIndicator /></p>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        <form className="input-area" onSubmit={handleSubmit} aria-label="Send message form">
          <input
            type="text"
            aria-label="Type your message"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Type your message here..."
            autoComplete="off"
            spellCheck="false"
          />
          <button type="submit" aria-label="Send message">➤</button>
        </form>
      </main>
    </div>
  );
}

export default App;
